-- The maps of Citi Field, Madison Square Garden and Barclays Center (Sean, 2026-10-29: the seating charts he sent as screenshots),
-- read the same way as the others: each level's sections clockwise by side. We draw our own map; only the numbers come from the charts.
-- Citi Field is drawn with home plate at the bottom (its chart is turned); the 200s are suites and left off. Madison Square Garden's
-- 400s are only on the West balcony; its 300s are the two Chase Bridges and the East balcony. Suites and VIP boxes are left off.

update public.ve_venues set layout = '{"field": "baseball", "ring_m": 900, "levels": [{"level": "100", "name": "Field level (100s, and the lettered and 14 to 16 sections behind home)", "sides": {"top": ["138", "140", "143"], "right": ["106GA", "107", "109", "110", "111", "112"], "br": ["114", "A"], "bottom": ["B", "C", "14", "D", "15", "E", "16", "F"], "bl": ["H", "121"], "left": ["123", "124", "126", "127", "128", "129"], "tl": ["133", "134"]}}, {"level": "300", "name": "300 level", "sides": {"right": ["310", "312"], "br": ["317"], "bottom": ["319", "321"], "bl": ["326", "328"], "left": ["332"], "tl": ["334", "336", "337"]}}, {"level": "400", "name": "400 level", "sides": {"right": ["401", "403", "404", "405", "407", "409", "410"], "bottom": ["413", "414", "415", "417"], "bl": ["419", "420", "422", "424"], "left": ["425", "426"], "tl": ["431", "433", "436"]}}, {"level": "500", "name": "500 level", "sides": {"right": ["502", "503", "504", "505", "506", "507", "508", "509", "510"], "br": ["512", "513"], "bottom": ["514", "515", "516"], "bl": ["518", "519", "520", "521", "522", "523"], "left": ["524", "525", "526", "527", "528", "529", "530", "531", "532"], "tl": ["535", "537"]}}]}'::jsonb where slug = 'citi-field';
