update public.ve_venues set layout = '{"field": "basketball", "ring_m": 500, "levels": [{"level": "1", "name": "Lower bowl (sections 1 to 31)", "sides": {"tl": ["3", "4"], "top": ["6", "7", "8", "9", "10"], "tr": ["12", "13"], "right": ["15", "16", "17"], "br": ["19", "20"], "bottom": ["22", "23", "24", "25", "26"], "bl": ["28", "29"], "left": ["31", "1"]}}, {"level": "100", "name": "100 level", "sides": {"tl": ["102", "104"], "top": ["105", "106", "107", "108", "109", "110", "111"], "tr": ["112", "114"], "right": ["117"], "br": ["118", "120"], "bottom": ["121", "122", "123", "125", "126", "127"], "bl": ["128", "129"]}}, {"level": "200", "name": "200 level", "sides": {"tl": ["203", "204"], "top": ["205", "206", "207", "209", "210", "211"], "tr": ["212", "213", "214"], "right": ["215", "217", "218"], "br": ["219", "220"], "bottom": ["221", "222", "223", "225", "226", "227"], "bl": ["228", "229"], "left": ["230", "202"]}}]}'::jsonb where slug = 'barclays-center';
